function fuelStretch(fuel, target) {
  let best = 0;
  for (let i = 0; i < fuel.length; i++) {
    let sum = 0;
    for (let j = i; j < fuel.length; j++) {
      sum += fuel[j];
      if (sum >= target) {
        if (best === 0 || j - i + 1 < best) best = j - i + 1;
        break;
      }
    }
  }
  return best;
}

function fuelStretch(fuel, target) {
  let best = Infinity, sum = 0, left = 0;
  for (let right = 0; right < fuel.length; right++) {
    sum += fuel[right];
    while (sum >= target) {
      best = Math.min(best, right - left + 1);
      sum -= fuel[left++];
    }
  }
  return best === Infinity ? 0 : best;
}
